mapper.select:
SELECT c.category_name AS categoryName, COUNT(*) AS cnt
FROM orders o
JOIN store_category sc ON sc.store_id = o.store_id
JOIN category c       ON c.category_id = sc.category_id
WHERE o.user_no = #{userNo}
  AND o.order_time >= #{since}
  AND o.order_state >= 3
GROUP BY c.category_name
ORDER BY cnt DESC
LIMIT #{limit}
